"""
Builds benchmarks/texture_layers.bb with blitzcc and runs it once for each number of layers asked for, printing the time per frame
and what the frames cost.

    python3 benchmarks/texture_layers.py [--layers 1,2,3,4] [--tiles N] [--passes N] [--sync] [common options, see --help]

The original Blitz3D works too (see flythrough.py). Without a display the program runs under xvfb-run (llvmpipe): the times are
then only a smoke test, the counts are exact on any GPU.
"""
import benchutil


def main():
    runner = benchutil.Runner("texture_layers", __doc__, frames=300)
    p = runner.parser
    p.add_argument("--layers", default="1,2,3,4", help="numbers of layers to run, one run each (default %(default)s)")
    p.add_argument("--tiles", type=int, default=12, help="tiles along each side of the field (default %(default)s)")
    p.add_argument("--passes", type=int, default=1, help="RenderWorld calls before every Flip (default %(default)s)")
    p.add_argument("--sync", action="store_true", help="wait for the GPU before every Flip (reads a pixel)")
    args = runner.parse()
    for layers in (int(v) for v in args.layers.split(",")):
        runner.run({"BENCH_LAYERS": layers, "BENCH_TILES": args.tiles, "BENCH_PASSES": args.passes, "BENCH_SYNC": int(args.sync)},
                   "%d layers on %d tiles" % (layers, args.tiles * args.tiles))
        runner.report(["layers      %12d on %d tiles" % (layers, args.tiles * args.tiles)])
        runner.save("%dlayers" % layers, ("layers", "tiles", "passes", "sync"))


if __name__ == "__main__":
    main()
